import { z } from "zod";
import {
  AuthenticationSubscription,
  ChargingData,
  DnnConfiguration,
  FlowRules,
  Nssai,
  QosFlows,
  SessionManagementSubscriptionData,
  SubscribedUeAmbr,
  Subscription,
  UpSecurity,
} from "../../api";
import { DEFAULT_5QI } from "../const";
